/* 유가(신주상장) 
 */
scwin.fn_calcation = function() {
    var list_tot = 0;
    var list_comm_sum = 0;
    var list_comm_sum_add = 0;
    var list_count = 0;

    // 상장방식:신주상장
    if (mxr_list_type.getValue() == "1") {
        for (i = 1; i <= dts_calcData.getTotalRow(); i++) {
            if (dts_calcData.getCellData(i, "LIST_SHRS") != "0" && dts_calcData.getCellData(i, "PARVAL") != "0") {
                var a = dts_calcData.getCellData(i, "LIST_SHRS");
                var b = dts_calcData.getCellData(i, "PARVAL");

                //건별 상장금액구하기
                dts_calcData.setCellData(i, "list_single_tot", eval(a) * eval(b));

                //총상장금액합계내기
                list_tot = eval(list_tot) + eval(dts_calcData.getCellData(i, "list_single_tot"));

                //건별 상장수수료 구하기 start //////////////////////////////////////////////
                var rt_rate = "0.0";
                var rt_rate2 = "0.0";
                //건별 상장수수료 구해오기.

                //주권, 집합투자증권 상장수수료계산
                if (mrx_commition_gubun.getValue() == "1" || mrx_commition_gubun.getValue() == "2") {
                    rt_rate = scwin.rate_StcokNew(list_tot);
                    list_comm_sum = Math.round(rt_rate);
                    rt_rate2 = scwin.rate_StcokNew(dts_calcData.getCellData(i, "list_single_tot"));
                    list_comm_sum_add = list_comm_sum_add + eval(rt_rate2);
                    //수익증권, 신주인수권증권 상장수수료계산

                } else if (mrx_commition_gubun.getValue() == "4") {
                    rt_rate = scwin.rate_Bw(list_tot);
                    list_comm_sum = rt_rate;
                    rt_rate2 = scwin.rate_Bw(dts_calcData.getCellData(i, "list_single_tot"));
                    list_comm_sum_add = list_comm_sum_add + eval(rt_rate2);
                } else if (mrx_commition_gubun.getValue() == "3") {
                    rt_rate = scwin.rate_Bw(list_tot);
                    list_comm_sum = rt_rate;
                    rt_rate2 = scwin.rate_Bw2(dts_calcData.getCellData(i, "list_single_tot"));
                    list_comm_sum_add = list_comm_sum_add + eval(rt_rate2);
                }
                //건별 상장수수료 구하기 end //////////////////////////////////////////////

            } else {
                dts_calcData.setCellData(i, "list_single_tot", "0");
            }
        }
        //신규상장수수료 최대한도 2억5,000만원
        if (mrx_commition_gubun.getValue() == "1" || mrx_commition_gubun.getValue() == "2") {
            if (list_comm_sum_add > 250000000) {
                list_comm_sum_add = "250000000";
            }
        }
        //집합투자증권, 수익증권은 1/3
        if (mrx_commition_gubun.getValue() == "2" || mrx_commition_gubun.getValue() == "3") {
            list_comm_sum = list_comm_sum * 1 / 3;
            if (mrx_commition_gubun.getValue() == "2") {
                list_comm_sum_add = list_comm_sum_add * 1 / 3;
            }
        }
        //수익증권은 최소 10만원
        if (mrx_commition_gubun.getValue() == "3") {
            if (list_comm_sum > 0 && list_comm_sum < 100000) {
                list_comm_sum = 100000;
            }
        }
        list_comm_sum = parseInt(list_comm_sum / 100) * 100;
        list_comm_sum_add = parseInt(list_comm_sum_add / 100) * 100;

        //총상장금액 세팅
        dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_tot", $c.stf.FormatNumberEx(list_tot, 3));

        //상장수수료 합계 
        dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum", $c.stf.FormatNumberEx(list_comm_sum, 3));
        if (mrx_commition_gubun.getValue() == "1") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("1000000", 3));
            if (list_comm_sum_add < 1000000) {
                list_comm_sum_add = "1000000";
            }
        } else if (mrx_commition_gubun.getValue() == "2") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("333300", 3));
            if (list_comm_sum_add < 333300) {
                list_comm_sum_add = "333300";
            }
        } else if (mrx_commition_gubun.getValue() == "3") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("100000", 3));
            if (list_comm_sum_add < 100000) {
                list_comm_sum_add = "100000";
            }
        } else if (mrx_commition_gubun.getValue() == "4") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("100000", 3));
            if (list_comm_sum_add < 100000) {
                list_comm_sum_add = "100000";
            }
        }
        if (list_comm_sum != 0) {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_add", $c.stf.FormatNumberEx(list_comm_sum_add, 3));
        } else {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_add", "");
        }
        //추가/재상장

    } else if (mxr_list_type.getValue() == "2") {
        for (i = 1; i <= dts_calcData.getTotalRow(); i++) {
            if (dts_calcData.getCellData(i, "LIST_SHRS") != "0" && dts_calcData.getCellData(i, "PARVAL") != "0") {
                list_count++;
                var a = dts_calcData.getCellData(i, "LIST_SHRS");
                var b = dts_calcData.getCellData(i, "PARVAL");

                //건별 상장금액구하기
                dts_calcData.setCellData(i, "list_single_tot", eval(a) * eval(b));

                //총상장금액합계내기
                list_tot = eval(list_tot) + eval(dts_calcData.getCellData(i, "list_single_tot"));

                //건별 상장수수료 구하기 start //////////////////////////////////////////////
                var rt_rate = "0.0";
                var rt_rate2 = "0.0";
                //건별 상장수수료 구해오기.

                //주권, 집합투자증권 상장수수료계산
                if (mrx_commition_gubun.getValue() == "1" || mrx_commition_gubun.getValue() == "2") {
                    rt_rate = scwin.rate_StcokAdd(list_tot);
                    list_comm_sum = Math.round(rt_rate);
                    rt_rate2 = scwin.rate_StcokAdd(dts_calcData.getCellData(i, "list_single_tot"));
                    list_comm_sum_add = list_comm_sum_add + eval(rt_rate2);
                    //건별 상장수수료 구하기 end //////////////////////////////////////////////

                }
            } else {
                dts_calcData.setCellData(i, "list_single_tot", "0");
            }
        }
        if (mrx_commition_gubun.getValue() == "2") {
            list_comm_sum = list_comm_sum * 1 / 3;
            list_comm_sum_add = list_comm_sum_add * 1 / 3;
        } else if (mrx_commition_gubun.getValue() == "3") {
            list_comm_sum = list_count * 100000;
            list_comm_sum_add = list_count * 100000;
        } else if (mrx_commition_gubun.getValue() == "4") {
            list_comm_sum = list_count * 300000;
            list_comm_sum_add = list_count * 300000;
        }
        list_comm_sum = parseInt(list_comm_sum / 100) * 100;
        list_comm_sum_add = parseInt(list_comm_sum_add / 100) * 100;

        //총상장금액 세팅
        dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_tot", $c.stf.FormatNumberEx(list_tot, 3));

        //상장수수료 합계 
        dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum", $c.stf.FormatNumberEx(list_comm_sum, 3));
        if (mrx_commition_gubun.getValue() == "1") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("250000", 3));
            if (list_comm_sum_add < 250000) {
                list_comm_sum_add = "250000";
            }
        } else if (mrx_commition_gubun.getValue() == "2") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("83300", 3));
            if (list_comm_sum_add < 83300) {
                list_comm_sum_add = "83300";
            }
        } else if (mrx_commition_gubun.getValue() == "3") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("100000", 3));
            if (list_comm_sum_add < 100000) {
                list_comm_sum_add = "100000";
            }
        } else if (mrx_commition_gubun.getValue() == "4") {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("300000", 3));
            if (list_comm_sum_add < 300000) {
                list_comm_sum_add = "300000";
            }
        }
        if (list_comm_sum != 0) {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_add", $c.stf.FormatNumberEx(list_comm_sum_add, 3));
        } else {
            dts_calcDataResult.setCellData(dts_calcDataResult.getRowPosition(), "list_comm_sum_add", "");
        }
    }
    //변경상장

    /*
		else if(mxr_list_type.CodeValue == "3"){
			for(i = 1; i <= dts_calcData.CountRow; i++) {
				if (dts_calcData.NameString(i,"LIST_SHRS") != "0" && dts_calcData.NameString(i,"PARVAL") != "0") {
					list_count++;
					var a = dts_calcData.NameString(i,"LIST_SHRS");
					var b = dts_calcData.NameString(i,"PARVAL");
					//건별 상장금액구하기
dts_calcData.setNameString(i,"list_single_tot",eval(a) * eval(b)) ;
					//총상장금액합계내기
					list_tot = eval(list_tot) + eval(dts_calcData.NameString(i,"list_single_tot"));
				} else {
dts_calcData.setNameString(i,"list_single_tot","0") ;
				}
			}
			if(mrx_commition_gubun.CodeValue == "1"){
				list_comm_sum = list_count * 2000000;
				list_comm_sum_add = list_count * 2000000;
			}else if(mrx_commition_gubun.CodeValue == "2"){
				list_comm_sum = list_count * 300000;
				list_comm_sum_add = list_count * 300000;
			}else if(mrx_commition_gubun.CodeValue == "3"){
				list_comm_sum = list_count * 100000;
				list_comm_sum_add = list_count * 100000;
			}else if(mrx_commition_gubun.CodeValue == "4"){
				list_comm_sum = list_count * 300000;
				list_comm_sum_add = list_count * 300000;
			}
			list_comm_sum = parseInt(list_comm_sum / 100) * 100;
			list_comm_sum_add = parseInt(list_comm_sum_add / 100) * 100;

			//총상장금액 세팅
