//코스닥 상장 수수료 계산
scwin.fn_calcation_cos = function() {
    var list_tot = 0;
    var list_comm_sum = 0;
    var list_comm_sum_add = 0;

    // 신규상장
    if (mxr_list_type_cos.getValue() == "1") {
        for (i = 1; i <= dts_calcDataCos.getTotalRow(); i++) {
            if (dts_calcDataCos.getCellData(i, "LIST_SHRS") != "0") {
                var a = dts_calcDataCos.getCellData(i, "LIST_SHRS");
                var b = dts_calcDataCos.getCellData(i, "PARVAL");

                //건별 상장금액구하기
                dts_calcDataCos.setCellData(i, "list_single_tot", eval(a) * eval(b));

                //총상장금액합계내기
                list_tot = eval(list_tot) + eval(dts_calcDataCos.getCellData(i, "list_single_tot"));

                //건별 상장수수료 구하기 start //////////////////////////////////////////////
                var rt_rate = "0.0";
                var rt_rate2 = "0.0";

                //총 상장금액에서 상장수수료
                /*fn_list_sum_add(mrx_commition_gubun_cos.CodeValue, list_tot);  
                rt_rate = eval(dts_list_fee_cos.NameString(1,"LIST_COMMON_SUM"));
                list_comm_sum = Math.round(rt_rate);
                */

                rt_rate = scwin.fn_cos_new_cal(mrx_commition_gubun_cos.getValue(), list_tot);
                list_comm_sum = Math.round(rt_rate);


                //부과 상장수수료				
                rt_rate2 = scwin.fn_cos_new_cal(mrx_commition_gubun_cos.getValue(), dts_calcDataCos.getCellData(i, "list_single_tot"));
                list_comm_sum_add = list_comm_sum_add + eval(rt_rate2);
            } else {
                dts_calcDataCos.setCellData(i, "list_single_tot", "0");
            }
        }
        list_comm_sum_add = parseInt(list_comm_sum_add / 100) * 100;

        //총상장금액 세팅
        dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_tot", $c.stf.FormatNumberEx(list_tot, 3));

        //상장수수료 합계 
        dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum", $c.stf.FormatNumberEx(list_comm_sum, 3));

        //상장수수료 최저한도
        if (mrx_commition_gubun_cos.getValue() == "2") {
            // 신주인수권증권
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("50000", 3));
        } else {
            // 주권,외국주권,외국주식예탁증권(DR)
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("1000000", 3));
        }

        //부과 상장수수료 
        if (mrx_commition_gubun_cos.getValue() != "2") {
            if (list_comm_sum_add < 1000000) {
                // 주권,외국주권,외국주식예탁증권(DR)
                list_comm_sum_add = "1000000";
            }
        } else {
            // 신주인수권증권
            if (list_comm_sum_add < 50000) {
                list_comm_sum_add = "50000";
            }
        }
        if (list_comm_sum != 0) {
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_add", $c.stf.FormatNumberEx(list_comm_sum_add, 3));
        } else {
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_add", "");
        }
    } else {
        // 코스닥 추가/변경/재상장	
        for (i = 1; i <= dts_calcDataCos.getTotalRow(); i++) {
            if (dts_calcDataCos.getCellData(i, "LIST_SHRS") != "0") {
                var a = dts_calcDataCos.getCellData(i, "LIST_SHRS");
                var b = dts_calcDataCos.getCellData(i, "PARVAL");

                //건별 상장금액구하기
                dts_calcDataCos.setCellData(i, "list_single_tot", eval(a) * eval(b));

                //총상장금액합계내기
                list_tot = eval(list_tot) + eval(dts_calcDataCos.getCellData(i, "list_single_tot"));

                //건별 상장수수료 구하기 start //////////////////////////////////////////////
                var rt_rate = "0.0";
                var rt_rate2 = "0.0";
                rt_rate = scwin.fn_cos_add_cal(mrx_commition_gubun_cos.getValue(), list_tot);
                list_comm_sum = Math.round(rt_rate);

                //부과 상장수수료
                rt_rate2 = scwin.fn_cos_add_cal(mrx_commition_gubun_cos.getValue(), dts_calcDataCos.getCellData(i, "list_single_tot"));
                list_comm_sum_add = list_comm_sum_add + eval(rt_rate2);
            } else {
                dts_calcDataCos.setCellData(i, "list_single_tot", "0");
            }
        }
        list_comm_sum_add = parseInt(list_comm_sum_add / 100) * 100;

        //총상장금액 세팅
        dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_tot", $c.stf.FormatNumberEx(list_tot, 3));

        //상장수수료 합계 
        dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum", $c.stf.FormatNumberEx(list_comm_sum, 3));

        //상장수수료 최저한도
        if (mrx_commition_gubun_cos.getValue() == "2") {
            // 신주인수권증권
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("50000", 3));
        } else {
            // 주권,외국주권,외국주식예탁증권(DR)
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("250000", 3));
        }

        //부과 상장수수료 
        if (mrx_commition_gubun_cos.getValue() != "2") {
            if (list_comm_sum_add < 250000) {
                // 주권,외국주권,외국주식예탁증권(DR)
                list_comm_sum_add = "250000";
            }
        } else {
            // 신주인수권증권
            if (list_comm_sum_add < 50000) {
                list_comm_sum_add = "50000";
            }
        }
        if (list_comm_sum != 0) {
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_add", $c.stf.FormatNumberEx(list_comm_sum_add, 3));
        } else {
            dts_calcDataResultCos.setCellData(dts_calcDataResultCos.getRowPosition(), "list_comm_sum_add", "");
        }
    }
};







/* 디지털증권 계산
 */
scwin.fn_calcation_digital = function() {
    var list_tot = 0;
    var list_comm_sum = 0;
    var list_comm_sum_add = 0;
    for (i = 1; i <= dts_calcDigital.getTotalRow(); i++) {
        if (dts_calcDigital.getCellData(i, "LIST_SHRS") != "0") {
            var a = dts_calcDigital.getCellData(i, "LIST_SHRS");
            var b = dts_calcDigital.getCellData(i, "PARVAL");
            if (b <= 0) continue;
            //건별 상장금액구하기
            dts_calcDigital.setCellData(i, "list_single_tot", eval(a) * eval(b));

            //총상장금액합계내기
            list_tot = eval(list_tot) + eval(dts_calcDigital.getCellData(i, "list_single_tot"));

            //건별 상장수수료 구하기 start //////////////////////////////////////////////
            var rt_rate = "0.0";
            var rt_rate2 = "0.0";
            rt_rate = scwin.fn_digital_cal(mxr_list_type_digital.getValue(), list_tot);
            list_comm_sum = Math.round(rt_rate);


            //부과 상장수수료				
            rt_rate2 = scwin.fn_digital_cal(mxr_list_type_digital.getValue(), dts_calcDigital.getCellData(i, "list_single_tot"));
            list_comm_sum_add = list_comm_sum_add + eval(rt_rate2);
        } else {
            dts_calcDigital.setCellData(i, "list_single_tot", "0");
        }
    }

    //list_comm_sum_add = parseInt(list_comm_sum_add / 100) * 100;
    //list_comm_sum = parseInt(list_comm_sum / 100) * 100;			
    //총상장금액 세팅
    dts_calcDigitalResult.setCellData(dts_calcDigitalResult.getRowPosition(), "list_tot", $c.stf.FormatNumberEx(list_tot, 3));

    //상장수수료 합계 
    //dts_calcDigitalResult.NameString(dts_calcDigitalResult.RowPosition,"list_comm_sum") = FormatNumberEx(list_comm_sum,3);

    //상장수수료 최저한도
    dts_calcDigitalResult.setCellData(dts_calcDigitalResult.getRowPosition(), "list_comm_sum_min", $c.stf.FormatNumberEx("100000", 3));

    //부과 상장수수료 			
    if (list_comm_sum_add < 100000) {
        list_comm_sum_add = "100000";
    }
    if (list_comm_sum != 0) {
        dts_calcDigitalResult.setCellData(dts_calcDigitalResult.getRowPosition(), "list_comm_sum_add", $c.stf.FormatNumberEx(list_comm_sum_add, 3));
    } else {
        dts_calcDigitalResult.setCellData(dts_calcDigitalResult.getRowPosition(), "list_comm_sum_add", "");
    }
};
scwin.trunc = function(value, npos) {
    var roundValue = makeRoundValue(npos);
    var multiValue = Math.pow(10, npos - 1);
    var temp = value - roundValue;
    temp = temp * multiValue;
    temp = Math.round(temp);
    temp = temp / multiValue;
    return temp;
};


/*
	코스닥 신규상장
*/
scwin.fn_cos_new_cal = function(type, total) {
    var rate = 0;
    if (total <= 50000000000) {
        // 500억원 이하
        rate = 1000000; // 100만원

    } else if (total > 50000000000 && total <= 70000000000) {
        // 500억원초과 ~ 700억원이하
        rate = 5000000 + (Math.ceil((total - 50000000000.0) / 1000000000)) * 70000; // 500만원 + 500억원 초과금액의 10억원당 7만원

    } else if (total > 70000000000 && total <= 100000000000) {
        // 700억원초과 ~ 1,000억원이하
        rate = 6400000 + (Math.ceil((total - 70000000000.0) / 1000000000)) * 60000; // 640만원 + 700억원 초과금액의 10억원당 6만원

    } else if (total > 100000000000 && total <= 200000000000) {
        // 1,000억원 초과 ~ 2,000억원이하
        rate = 8200000 + (Math.ceil((total - 100000000000.0) / 1000000000)) * 50000; // 820만원 + 1,000억원 초과금액의 10억원당 5만원

    } else if (total > 200000000000 && total <= 300000000000) {
        // 2,000억원 초과 ~ 3,000억원이하
        rate = 13200000 + (Math.ceil((total - 200000000000.0) / 1000000000)) * 40000; // 1,320만원 + 2,000억원 초과금액의 10억원당 4만원

    } else if (total > 300000000000 && total <= 400000000000) {
        // 3,000억원 초과 ~ 4,000억원이하
        rate = 17200000 + (Math.ceil((total - 300000000000.0) / 1000000000)) * 30000; // 1,720만원 + 3,000억원 초과금액의 10억원당 3만원

    } else if (total > 400000000000 && total <= 500000000000) {
        // 4,000억원 초과 ~ 5,000억원이하
        rate = 20200000 + (Math.ceil((total - 400000000000.0) / 1000000000)) * 20000; // 2,020만원 + 4,000억원 초과금액의 10억원당 2만원

    } else if (total > 500000000000) {
        // 5,000억원 초과
        rate = 22200000 + (Math.ceil((total - 500000000000.0) / 1000000000)) * 10000; // 2,220만원 + 5000억원 초과금액의 10억원당 1만원

    }
    if (rate > 200000000) {
        // 최고한도액 2억원
        rate = 200000000;
    }
    if (type == 1) {
        return rate;
    } else {
        return rate * 1 / 3;
    }
};


/*
	코스닥 추가/변경/재상장
*/
scwin.fn_cos_add_cal = function(type, total) {
    var rate = 0;
    if (total <= 10000000000) {
        // 100억원 이하
        rate = 250000 + (Math.ceil((total - 1000000000.0) / 1000000000)) * 250000; // 10억원당 25만원(최저한도액 25만원)

    } else if (total > 10000000000 && total <= 30000000000) {
        // 100억원초과 ~ 300억원이하
        rate = 2500000 + (Math.ceil((total - 10000000000.0) / 1000000000)) * 90000; // 250만원 + 100억원 초과금액의 10억원당 9만원

    } else if (total > 30000000000 && total <= 50000000000) {
        // 300억원초과 ~ 500억원이하
        rate = 4300000 + (Math.ceil((total - 30000000000.0) / 1000000000)) * 80000; // 430만원 + 300억원 초과금액의 10억원당 8만원

    } else if (total > 50000000000 && total <= 70000000000) {
        // 500억원 초과 ~ 700억원이하
        rate = 5900000 + (Math.ceil((total - 50000000000.0) / 1000000000)) * 70000; // 590만원 + 500억원 초과금액의 10억원당 7만원

    } else if (total > 70000000000 && total <= 100000000000) {
        // 700억원 초과 ~ 1,000억원이하
        rate = 7300000 + (Math.ceil((total - 70000000000.0) / 1000000000)) * 60000; // 730만원 + 700억원 초과금액의 10억원당 6만원

    } else if (total > 100000000000 && total <= 200000000000) {
        // 1,000억원 초과 ~ 2,000억원이하
        rate = 9100000 + (Math.ceil((total - 100000000000.0) / 1000000000)) * 50000; // 910만원 + 1,000억원 초과금액의 10억원당 5만원

    } else if (total > 200000000000 && total <= 500000000000) {
        // 2,000억원 초과 ~ 5,000억원이하
        rate = 14100000 + (Math.ceil((total - 200000000000.0) / 1000000000)) * 40000; // 1,410만원 + 2,000억원 초과금액의 10억원당 4만원

    } else if (total > 500000000000) {
        // 5,000억원 초과
        rate = 26100000 + (Math.ceil((total - 500000000000.0) / 1000000000)) * 20000; // 2,610만원 + 5000억원 초과금액의 10억원당 2만원

    }
    if (rate > 50000000) {
        // 최고한도액 5천만원
        rate = 50000000;
    }
    if (type == 1) {
        return rate;
    } else {
        return rate * 1 / 3;
    }
};




/*
	디지털증권  계산
*/
scwin.fn_digital_cal = function(type, total) {
    var rate = 100000;
    if (total >= 3000000000 && total < 5000000000) {
        // 30억원이상 ~ 50억원 미만
        rate = 100000; // 30만원

    } else if (total >= 5000000000 && total < 10000000000) {
        // 50억원이상 ~ 100억원이만
        rate = 233300; // 70만원

    } else if (total >= 10000000000 && total < 15000000000) {
        // 100억원이상~ 150억원미만
        rate = 333300; // 100만원

    } else if (total >= 15000000000 && total < 25000000000) {
        // 150억원이상 ~ 250억원미만
        rate = 400000; // 120만원

    } else if (total >= 25000000000 && total < 50000000000) {
        // 250억원이상 ~ 500억원미만
        rate = 433300; // 130만원

    } else if (total >= 50000000000 && total < 100000000000) {
        // 500억원 이상 ~ 1000억원미만
        rate = 466600; // 140만원

    } else if (total >= 100000000000 && total < 200000000000) {
        //  1000억원 이상 ~ 2,000억원미만
        rate = 500000; // 150만원

    } else if (total >= 200000000000 && total < 500000000000) {
        //2,000억원 이상 ~ 5,000억원미만
        rate = 533300; // 160만원

    } else if (total >= 500000000000) {
        // 5,000억원 이상
        rate = 566600; // 170만원

    }

    /*
    if (rate*1/3 <100000){
    		return 100000;
    	}else{
    		return rate * 1/3;
    	 }
    	 */
    return rate;
};

