scwin.fn_CheckForm = function(jobType) {
    if ($c.stf.getObjectValue(txb_ISUR_CD_R) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD_R.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_FEE_EXMPT_STRT_DD) == "") {
        $c.win.alert("[상장수수료면제시작일]을 입력하세요.");
        edt_LIST_FEE_EXMPT_STRT_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_FEE_EXMPT_END_DD) == "") {
        $c.win.alert("[상장수수료면제종료일]을 입력하세요.");
        edt_LIST_FEE_EXMPT_END_DD.focus();
        return false;
    }
    if (parseInt(edt_LIST_FEE_EXMPT_STRT_DD.getValue(), 10) >= parseInt(edt_LIST_FEE_EXMPT_END_DD.getValue(), 10)) {
        $c.win.alert("[상장수수료면제시작일]은 [상장수수료면제종료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if (!scwin.fn_double_inout_3(jobType)) {
        return false;
    }
    if ($c.stf.getObjectValue(cmb_LIST_FEE_EXMPT_RSN_CD) == "") {
        $c.win.alert("[상장수수료면제사유]를 선택하세요.");
        cmb_LIST_FEE_EXMPT_RSN_CD.focus();
        return false;
    }
    return true;
};
