    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item_3)";
    trs_Save.Post();
};
scwin.calc_elw = function(i) {
    //상장
    var rate = "0.0";
    /*if (i >= 1000000000.0 && i < 2000000000.0) {
            rate = 300000 +  (i - 1000000000.0) * 0.00025   ;
        } else if (i >= 2000000000.0 && i < 5000000000.0) {
            rate = 550000 +  (i - 2000000000.0) * 0.000183   ;
        } else if (i >= 5000000000.0 && i < 10000000000.0) {
            rate = 1100000 +  (i - 5000000000.0) * 0.00016  ;
        } else if (i >= 10000000000.0 && i < 50000000000.0) {
            rate = 1900000 +  (i - 10000000000.0) * 0.00015   ;
        } else if (i >= 50000000000.0 && i < 100000000000.0) {
            rate = 7900000 +  (i - 50000000000.0) * 0.00004  ;
        } else if (i >= 100000000000.0 && i < 500000000000.0) {
            rate = 9900000 +  (i - 100000000000.0) * 0.00003   ;
        } else if (i >= 500000000000.0 && i < 1000000000000.0) {
           rate = 21900000 +  (i - 500000000000.0) * 0.00002  ;
        }else if (i >= 1000000000000.0){
		     rate = 31900000 +  (i - 1000000000000.0) * 0.00001   ;
		}*/

    if (i >= 1000000000.0 && i < 2000000000.0) {
        //10억 이상 20억 미만
        rate = 200000; //20만원

    } else if (i >= 2000000000.0 && i < 5000000000.0) {
        //20억 이상 50억 미만
        rate = (310000 + (Math.floor((i - 2000000000.0) / 1000000000)) * 90000); //31만원 + 20억 초과금액의 10억당 9만원

    } else if (i >= 5000000000.0 && i < 10000000000.0) {
        //50억이상 100억 미만
        rate = (580000 + (Math.floor((i - 5000000000.0) / 1000000000)) * 80000); //58만원 + 50억 초과금액의 10억당 8만원

    } else if (i >= 10000000000.0 && i < 50000000000.0) {
        //100억 이상 500억 미만
        rate = (980000 + (Math.floor((i - 10000000000.0) / 1000000000)) * 70000); //98만원 + 100억 초과금액의 10억당 7만원

    } else if (i >= 50000000000.0 && i < 100000000000.0) {
        //500억이상 1000억 미만
        rate = (3780000 + (Math.floor((i - 50000000000.0) / 1000000000)) * 30000); //378만원 + 500억 초과금액의 10억당 3만원

    } else if (i >= 100000000000.0) {
        rate = (5280000 + (Math.floor((i - 100000000000.0) / 1000000000)) * 10000); //528만원 + 1000억 초과금액의 10억당 1만원

    }
    return rate;
};
scwin.calc_etf = function(i) {
    //상장
    var rate = "0.0";
    var wonUnit = 100000000; //억단위
    var tenHM = 1000000000; //10억단위

    /*2020 03. 20수수료율 변경*/
    if (i <= (500 * wonUnit)) {
        //500억이하일 경우 
        rate = 1000000 / 3; //- 수수료 100만원

    } else if (i > (500 * wonUnit) && i <= (1000 * wonUnit)) {
        //5백억 ~ 1천억
        rate = (5000000 + (Math.ceil((i - (500 * wonUnit)) / tenHM)) * 75000) / 3; // - (500만원 + ( 500억 초과금액의 10억당 7.5만원)) / 3

    } else if (i > (1000 * wonUnit) && i <= (2000 * wonUnit)) {
        //1천억 ~ 2천억
        rate = (8750000 + (Math.ceil((i - (1000 * wonUnit)) / tenHM)) * 60000) / 3; //- (875만원 + ( 1000억 초과금액의 10억당 6만원)) / 3

    } else if (i > (2000 * wonUnit) && i <= (5000 * wonUnit)) {
        //2천억 ~ 5천억
        rate = (14750000 + (Math.ceil((i - (2000 * wonUnit)) / tenHM)) * 45000) / 3; // - (1,475만원 + ( 2000억 초과금액의 10억당4.5만원)) / 3

    } else if (i > (5000 * wonUnit) && i <= (20000 * wonUnit)) {
        //5천억 ~ 2조
        rate = (28250000 + (Math.ceil((i - (5000 * wonUnit)) / tenHM)) * 35000) / 3; // - (2,825만원 + ( 5000억 초과금액의 10억당3.5만원)) / 3

    } else if (i > (20000 * wonUnit) && i <= (50000 * wonUnit)) {
        //2조 ~ 5조
        rate = (80750000 + (Math.ceil((i - (20000 * wonUnit)) / tenHM)) * 25000) / 3; // - (8,075만원 + ( 2조 초과금액의 10억당2.5만원)) / 3

    } else if (i > (50000 * wonUnit) && i <= (100000 * wonUnit)) {
        //5조!~ 10조
        rate = (155750000 + (Math.ceil((i - (50000 * wonUnit)) / tenHM)) * 15000) / 3; // - (15,575만원 + ( 5조 초과금액의 10억당1.5만원)) / 3

    } else if (i > (100000 * wonUnit)) {
        //10 조원 초과
        rate = (230750000 + (Math.ceil((i - (100000 * wonUnit)) / tenHM)) * 5000) / 3; // - (23,075만원 + (10조 초과금액의 10억당0.5만원)) / 3

    }
    if (rate > 83333300) {
        rate = 83333300;
    }
    return Math.floor(rate / 100) * 100;
};
