scwin.btn_calc_sec_onclick = function() {
    var totalAmt = 0;
    var totalFee = 0;
    if (mxr_secu_gubun.getValue() == 1) {
        for (i = 1; i <= dts_calcElw.getTotalRow(); i++) {
            var elwTotAmt = eval(dts_calcElw.getCellData(i, "ELW_TOT_AMT"));
            var elwFee = 0;
            if (elwTotAmt != 0) {
                elwFee = parseInt(scwin.calc_elw(elwTotAmt) / 100) * 100;
                //dts_calcElw.NameString(i,"ELW_FEE")  =  FormatNumberEx(elwFee,3);
                dts_calcElw.setCellData(i, "ELW_FEE", elwFee);
            }
            totalAmt += elwTotAmt;
            totalFee += elwFee;
        }
    } else if (mxr_secu_gubun.getValue() == 2) {
        for (i = 1; i <= dts_calcEtf.getTotalRow(); i++) {
            var trstOrgnVal = eval(dts_calcEtf.getCellData(i, "TRST_ORGN_VAL"));
            var etfFee = 0;
            if (trstOrgnVal != 0) {
                etfFee = parseInt(scwin.calc_etf(trstOrgnVal) / 100) * 100;
                //dts_calcEtf.NameString(i,"ETF_FEE")  =  FormatNumberEx(etfFee, 3);
                dts_calcEtf.setCellData(i, "ETF_FEE", etfFee);
            }
            totalAmt += trstOrgnVal;
            totalFee += etfFee;
        }
    } else if (mxr_secu_gubun.getValue() == 4) {
        for (i = 1; i <= dts_calcPf.getTotalRow(); i++) {
            var trstOrgnVal = eval(dts_calcPf.getCellData(i, "TRST_ORGN_VAL"));
            var etfFee = 0;
            if (trstOrgnVal != 0) {
                etfFee = parseInt(scwin.calc_etf(trstOrgnVal) / 100) * 100;
                //dts_calcEtf.NameString(i,"ETF_FEE")  =  FormatNumberEx(etfFee, 3);
                dts_calcPf.setCellData(i, "ETF_FEE", etfFee);
            }
            totalAmt += trstOrgnVal;
            totalFee += etfFee;
        }
    } else if (mxr_secu_gubun.getValue() == 3) {
        for (i = 1; i <= dts_calcEtn.getTotalRow(); i++) {
            var isuOrgnVal = eval(dts_calcEtn.getCellData(i, "ISU_ORGN_VAL"));
            var etnFee = 0;
            if (isuOrgnVal != 0) {
                etnFee = parseInt(scwin.calc_etn(isuOrgnVal) / 100) * 100;
                dts_calcEtn.setCellData(i, "ETN_FEE", etnFee);
            }
            totalAmt += isuOrgnVal;
            totalFee += etnFee;
        }
    }
    tbxTotAmt.setValue($c.stf.FormatNumberEx(totalAmt, 3));
    tbxTotFee.setValue($c.stf.FormatNumberEx(totalFee, 3));
    $c.win.alert('계산이 완료 되었습니다');
};
