    //dts_calcEtn.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    for (i = 0; i < 16; i++) {
        dts_calcEtn.insertRow();
    }
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save_3, fn_save_3); // 저장
    buttonSet.setUpdateInfo(btn_Update_3, fn_update_3); // 수정
    buttonSet.setDeleteInfo(btn_Delete_3, fn_delete_3); // 삭제

    buttonSet.setInsertStatus();
    if (js_dep_cd.substring(0, 2) != '34') {
        //코스닥공시총괄팀
        $c.stf.showObj(panel_Button, false);
    }
    //showObj(panel_4, false);

    $c.stf.showObj(pan_elw, true);
    $c.stf.showObj(grd_elw, true);
    //showObj(pan_etf ,  false);
    $c.stf.showObj(pan_etf_etn, false);
    $c.stf.showObj(grd_etf, false);
    $c.stf.showObj(grd_pf, false);
    $c.stf.showObj(grd_etn, false);
    if (mktId == "1") {
        mxr_list_type.setValue("2");
        scwin.changeStkSel();
    }


    ////////////////////////////////////////////////// 20230822 디지털증권 추가 //////////////////////////////////////////////////	

    //dts_calcDigital.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    for (i = 0; i < 16; i++) {
        dts_calcDigital.insertRow();
    }
    //dts_calcDigitalResult.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_calcDigitalResult.insertRow();
    ///////////////////////////////////////////////////////////////////////////////////////////////////

};
