scwin.mxr_list_type_cos_OnSelChange = function() {
    if (mxr_list_type_cos.getValue() == "1") {
        // 코스닥 신규
        $c.stf.showObj(pan_cosNew, true);
        $c.stf.showObj(pan_cosAdd, false);
        if (mrx_commition_gubun_cos.getValue() == "2") {
            // 신주인수권증권
            $c.stf.showObj(pan_NewSub1, false);
            $c.stf.showObj(pan_NewSub2, true);
        } else {
            $c.stf.showObj(pan_NewSub1, true);
            $c.stf.showObj(pan_NewSub2, false);
        }
    } else if (mxr_list_type_cos.getValue() == "2") {
        // 추가/변경/재상장
        $c.stf.showObj(pan_cosNew, false);
        $c.stf.showObj(pan_cosAdd, true);
        if (mrx_commition_gubun_cos.getValue() == "2") {
            // 신주인수권증권
            $c.stf.showObj(pan_AddSub1, false);
            $c.stf.showObj(pan_AddSub2, true);
        } else {
            $c.stf.showObj(pan_AddSub1, true);
            $c.stf.showObj(pan_AddSub2, false);
        }
    }
};
